                    top_pixels.append(c)
            elif c == 5 and 3 <= r <= 4:
                top_pixels.append(c)
            elif c == 11 and 3 <= r <= 4:
                top_pixels.append(c)

            # Bottom loop (rows 10-12)
            bottom_pixels = []
            if r == 12 and 5 <= c <= 11:
                bottom_pixels.append(c)
            elif r == 10 and 5 <= c <= 11:
                # Skip col 7-9 for separator
                if c not in [7, 8, 9]:
                    bottom_pixels.append(c)
            elif c == 5 and 10 <= r <= 11:
                bottom_pixels.append(c)
            elif c == 11 and 10 <= r <= 11:
                bottom_pixels.append(c)

            if c in top_pixels or c in bottom_pixels:
